svg.script:
(async () => {
  const say = message => { document.querySelector('text').textContent = message; };
  try {
    if (!('serviceWorker' in navigator) || !self.caches) throw new Error('This browser cannot run WebBlox here.');
    const base = location.href.replace(/[?#].*$/, '').replace(/[^/]*$/, '');
    const PAYLOAD = base + '__payload__';
    const cache = await caches.open('webblox-boot');
    const stored = await cache.match(PAYLOAD);
    let changed = false;
    if (parent !== self) {
      const reply = await new Promise(resolve => {
        addEventListener('message', function listen(event) {
          if (event.source !== parent || !event.data || !/^webblox-(payload|go)$/.test(event.data.type)) return;
          removeEventListener('message', listen);
          resolve(event.data);
        });
        parent.postMessage({ type: 'webblox-boot', have: stored ? stored.headers.get('x-webblox-version') : '' }, '*');
      });
      if (reply.type === 'webblox-payload') {
        say('Unpacking WebBlox');
        await cache.put(PAYLOAD, new Response(reply.body, { headers: { 'Content-Type': 'application/json', 'x-webblox-version': reply.version } }));
        changed = true;
      }
    } else if (!stored) {
      throw new Error('Open webblox.html to start WebBlox.');
    }
    const reg = await navigator.serviceWorker.register(base + 'sw.js?mode=wisp', { scope: base });
    const worker = reg.installing || reg.waiting || reg.active;
    if (worker.state !== 'activated') {
      await new Promise((resolve, reject) => worker.addEventListener('statechange', () => {
        if (worker.state === 'activated') resolve();
        if (worker.state === 'redundant') reject(new Error('The WebBlox service worker failed to install. Reload to try again.'));
      }));
    }
    if (changed && reg.active) {
      await new Promise(resolve => {
        const channel = new MessageChannel();
        channel.port1.onmessage = resolve;
        reg.active.postMessage({ type: 'webblox-payload-changed' }, [channel.port2]);
        setTimeout(resolve, 2000);
      });
    }
    location.replace(base + decodeURIComponent(location.hash.slice(1)));
  } catch (err) {
    say(err.message || String(err));
  }
})();
